package com.hugorunning.app;
import android.app.*;import android.os.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.content.*;import android.net.Uri;import android.view.*;import android.widget.*;import java.util.*;
public class MainActivity extends Activity{
 LinearLayout box;SharedPreferences p;ArrayList<Race> races=new ArrayList<>();int blue=Color.rgb(12,74,160),orange=Color.rgb(255,112,25),light=Color.rgb(244,248,253);
 static class Race{String n,l,q;Race(String a,String b,String c){n=a;l=b;q=c;}}
 TextView tx(String s,int z){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(Color.rgb(28,43,65));v.setPadding(18,10,18,10);return v;}
 GradientDrawable bg(int c,int rad){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(rad);return g;}
 Button bt(String s,int c){Button b=new Button(this);b.setText(s);b.setTextSize(16);b.setTextColor(Color.WHITE);b.setAllCaps(false);b.setBackground(bg(c,28));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(8,8,8,8);b.setLayoutParams(lp);return b;}
 public void onCreate(Bundle b){super.onCreate(b);p=getSharedPreferences("hugo",0);seed();home();}
 void seed(){races.add(new Race("Carrera de la Mujer por la Igualdad","Córdoba","Carrera Mujer Igualdad Córdoba infantil reglamento 2026"));races.add(new Race("XXI Ruta del Aceite","La Victoria","Ruta Aceite La Victoria carrera infantil reglamento"));races.add(new Race("Memorial Joaquín Sánchez","La Carlota","Memorial Joaquín Sánchez La Carlota carrera infantil"));races.add(new Race("XXI Legua Villa de Fernán Núñez","Fernán Núñez","Legua Fernán Núñez carrera infantil reglamento"));races.add(new Race("Ruta de la Miel","Hornachuelos","Ruta Miel Hornachuelos carrera infantil reglamento"));races.add(new Race("Carrera Nocturna de Alcolea","Alcolea","Carrera Nocturna Alcolea infantil reglamento"));races.add(new Race("C.P. Peñarroya-Pueblonuevo","Peñarroya-Pueblonuevo","Carrera Popular Peñarroya infantil reglamento"));races.add(new Race("C.P. Ciudad de Aguilar","Aguilar de la Frontera","Carrera Popular Ciudad Aguilar infantil reglamento"));}
 void base(){getWindow().setStatusBarColor(blue);ScrollView s=new ScrollView(this);s.setBackgroundColor(light);box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(22,20,22,45);s.addView(box);setContentView(s);}
 void title(String sub){TextView h=tx("🏃 HUGO RUNNING",30);h.setTextColor(blue);h.setTypeface(null,1);box.addView(h);TextView x=tx(sub,16);x.setTextColor(Color.DKGRAY);box.addView(x);}
 void home(){base();title("Carreras infantiles · Córdoba y alrededores");TextView hero=tx("¡Encuentra la próxima carrera de Hugo!\nBusca, comprueba su categoría y guarda todos los datos importantes.",20);hero.setTextColor(Color.WHITE);hero.setBackground(bg(blue,35));hero.setPadding(24,28,24,28);box.addView(hero);Button search=bt("🔎  BUSCAR CARRERAS AHORA",orange);search.setOnClickListener(v->searchMenu());box.addView(search);Button all=bt("📅  CARRERAS ENCONTRADAS",blue);all.setOnClickListener(v->list(false));box.addView(all);Button mine=bt("⭐  MIS CARRERAS DE HUGO",blue);mine.setOnClickListener(v->list(true));box.addView(mine);box.addView(tx("Filtros: Córdoba · Provincia · 75 km · Infantil 8–9 años",14));}
 void searchMenu(){base();title("Buscar carreras");box.addView(tx("Elige el tipo de búsqueda. Localiza pruebas, reglamentos, horarios e inscripciones actualizadas.",17));String[] z={"Córdoba capital","Provincia de Córdoba","Córdoba + 75 km","Cross y atletismo infantil","Milla / Legua infantil","Carreras solidarias infantiles"};String[] q={"carreras infantiles Córdoba 2026 inscripción reglamento","carreras populares infantiles provincia Córdoba 2026","carreras infantiles cerca Córdoba 75 km 2026","cross atletismo infantil Córdoba 2026","milla legua infantil Córdoba 2026","carrera solidaria infantil Córdoba 2026"};for(int i=0;i<z.length;i++){final int k=i;Button b=bt("🔎 "+z[i],i==2?orange:blue);b.setOnClickListener(v->web(q[k]));box.addView(b);}Button b=bt("← Volver",Color.DKGRAY);b.setOnClickListener(v->home());box.addView(b);}
 void web(String q){startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://www.google.com/search?q="+Uri.encode(q))));}
 void list(boolean only){base();title(only?"Mis carreras de Hugo":"Carreras encontradas");int count=0;for(int i=0;i<races.size();i++){if(only&&!p.getBoolean("r"+i,false))continue;count++;final int k=i;Race r=races.get(i);LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(16,14,16,14);card.setBackground(bg(Color.WHITE,25));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.setMargins(5,8,5,8);card.setLayoutParams(cp);TextView n=tx(r.n,19);n.setTextColor(blue);n.setTypeface(null,1);card.addView(n);card.addView(tx("📍 "+r.l+"   👦 Infantil",15));if(p.getBoolean("r"+i,false)){TextView ok=tx("✓ HUGO APUNTADO",15);ok.setTextColor(Color.rgb(0,130,70));ok.setTypeface(null,1);card.addView(ok);}Button b=bt("Ver ficha completa  ›",blue);b.setOnClickListener(v->detail(k));card.addView(b);box.addView(card);}if(count==0)box.addView(tx("Todavía no has marcado ninguna carrera para Hugo.",17));Button back=bt("← Inicio",Color.DKGRAY);back.setOnClickListener(v->home());box.addView(back);}
 void detail(int i){base();Race r=races.get(i);title(r.n);TextView loc=tx("📍 "+r.l,18);loc.setTextColor(blue);box.addView(loc);String[] data={"👦 EDAD DE HUGO\n8–9 años","🏃 CATEGORÍA Y DISTANCIA\nPendiente de comprobar en reglamento oficial","📅 FECHA\nPendiente de verificación","⏰ HORA DE SALIDA INFANTIL\nPendiente de publicación","🎽 RECOGIDA DE DORSAL\nPendiente de publicación","📌 LUGAR DE RECOGIDA\nPendiente de publicación","💶 PRECIO\nPendiente de verificación","🏁 SALIDA Y RECORRIDO\nPendiente de verificación","📝 DOCUMENTACIÓN / NORMAS\nPendiente de reglamento oficial"};for(String d:data){TextView v=tx(d,16);v.setBackground(bg(Color.WHITE,22));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(4,6,4,6);v.setLayoutParams(lp);box.addView(v);}Button info=bt("🌐 BUSCAR DATOS OFICIALES DE ESTA CARRERA",orange);info.setOnClickListener(v->web(r.q+" dorsal horario recogida categoría 8 9 años inscripción"));box.addView(info);boolean y=p.getBoolean("r"+i,false);Button mark=bt(y?"✓ HUGO ESTÁ APUNTADO":"☆ MARCAR HUGO APUNTADO",y?Color.rgb(0,145,80):blue);mark.setOnClickListener(v->{p.edit().putBoolean("r"+i,!p.getBoolean("r"+i,false)).apply();detail(i);});box.addView(mark);Button back=bt("← Volver a carreras",Color.DKGRAY);back.setOnClickListener(v->list(false));box.addView(back);}
}
